using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace NexaLauncher.Desktop;

internal static class NexaApplicationIcon
{
    private const string IconBase64 = "";

    public static ImageSource Create()
    {
        var bytes = Convert.FromBase64String(IconBase64);
        using var stream = new MemoryStream(bytes, writable: false);
        var decoder = BitmapDecoder.Create(stream, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
        return decoder.Frames.OrderByDescending(frame => frame.PixelWidth).First();
    }
}
